files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #e0e0e0;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 420px;
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: #f0f0f0;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 24px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 24px;
  aspect-ratio: 1 / 1;
}

.tile {
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  position: relative;
  font-size: 0;
  padding: 0;
  min-width: 0;
  min-height: 0;
}

.tile:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
  z-index: 1;
}

.tile:hover {
  transform: scale(1.05);
  box-shadow: 0 0 0 2px #ffffff80;
}

.tile:active {
  transform: scale(0.95);
}

.tile.selected {
  box-shadow: 0 0 0 3px #ffffff;
  transform: scale(1.05);
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  font-size: 1.1rem;
  min-height: 2rem;
}

.counter {
  font-weight: 600;
  color: #c0c0d0;
}

.solved {
  font-weight: 700;
  color: #6ee7b7;
  font-size: 1.3rem;
  letter-spacing: 0.5px;
}

.btn {
  display: inline-block;
  background: #5b5bd6;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  width: 100%;
}

.btn:hover {
  background: #6e6ee8;
}

.btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.btn:active {
  background: #4a4ac0;
  transform: scale(0.97);
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }

  h1 {
    font-size: 1.3rem;
  }

  .grid {
    gap: 6px;
  }

  .btn {
    padding: 10px 24px;
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  const COLORS = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f'];
  const SIZE = 4;

  const gridEl = document.getElementById('grid');
  const swapCountEl = document.getElementById('swap-count');
  const solvedMsgEl = document.getElementById('solved-message');
  const shuffleBtn = document.getElementById('shuffle-btn');

  let board = [];
  let selected = null;
  let swaps = 0;

  function createSolvedBoard() {
    const b = [];
    for (let r = 0; r < SIZE; r++) {
      const row = [];
      for (let c = 0; c < SIZE; c++) {
        row.push(r);
      }
      b.push(row);
    }
    return b;
  }

  function shuffleBoard() {
    const flat = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        flat.push(r);
      }
    }
    for (let i = flat.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [flat[i], flat[j]] = [flat[j], flat[i]];
    }
    const b = [];
    for (let r = 0; r < SIZE; r++) {
      b.push(flat.slice(r * SIZE, (r + 1) * SIZE));
    }
    return b;
  }

  function isSolved() {
    for (let r = 0; r < SIZE; r++) {
      const first = board[r][0];
      for (let c = 1; c < SIZE; c++) {
        if (board[r][c] !== first) return false;
      }
    }
    return true;
  }

  function isAdjacent(r1, c1, r2, c2) {
    return Math.abs(r1 - r2) + Math.abs(c1 - c2) === 1;
  }

  function render() {
    gridEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const colorIndex = board[r][c];
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'tile';
        btn.style.backgroundColor = COLORS[colorIndex];
        btn.dataset.row = r;
        btn.dataset.col = c;
        btn.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}, color ${colorIndex + 1}`);
        btn.addEventListener('click', onTileClick);
        if (selected && selected.r === r && selected.c === c) {
          btn.classList.add('selected');
        }
        gridEl.appendChild(btn);
      }
    }
    swapCountEl.textContent = `Swaps: ${swaps}`;
    solvedMsgEl.hidden = !isSolved();
  }

  function onTileClick(e) {
    const r = parseInt(e.currentTarget.dataset.row, 10);
    const c = parseInt(e.currentTarget.dataset.col, 10);

    if (!selected) {
      selected = { r, c };
      render();
      return;
    }

    if (selected.r === r && selected.c === c) {
      selected = null;
      render();
      return;
    }

    if (isAdjacent(selected.r, selected.c, r, c)) {
      const temp = board[selected.r][selected.c];
      board[selected.r][selected.c] = board[r][c];
      board[r][c] = temp;
      swaps++;
      selected = null;
      render();
    } else {
      selected = { r, c };
      render();
    }
  }

  function startNewGame() {
    board = shuffleBoard();
    swaps = 0;
    selected = null;
    render();
  }

  shuffleBtn.addEventListener('click', startNewGame);

  board = shuffleBoard();
  render();
})();
